// ***************
// Filename: spi_flash_ctrl_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of spi_flash_ctrl: joins the register map
//   spi_flash_ctrl_regs (modport regs) and the logic spi_flash_ctrl (modport
//   core). cfg_* go from the register map to the logic (register values, _wr
//   write pulses, _rd read pulses), sts_* come back (values read, _set / _clr
//   hardware set / clear pulses). A logic block ties every sts_* member it
//   does not use to 0. Generated by ip/scripts/regmap_gen.py from
//   spi_flash_ctrl_regs.json: edit the JSON and regenerate.
// Date: 2026-10-20
interface spi_flash_ctrl_regs_if ();
  logic [32-1:0] cfg_cmd;
  logic cfg_cmd_wr;
  logic [24-1:0] cfg_addr;
  logic cfg_addr_wr;
  logic [16-1:0] cfg_len;
  logic cfg_len_wr;
  logic [16-1:0] cfg_clkdiv;
  logic cfg_clkdiv_wr;
  logic [3-1:0] sts_status;
  logic [3-1:0] cfg_status;
  logic cfg_status_wr;
  logic cfg_irq_en;
  logic cfg_irq_en_wr;

  modport regs (output cfg_cmd, cfg_cmd_wr, cfg_addr, cfg_addr_wr, cfg_len, cfg_len_wr, cfg_clkdiv,
    cfg_clkdiv_wr, cfg_status, cfg_status_wr, cfg_irq_en, cfg_irq_en_wr, input sts_status);
  modport core (output sts_status, input cfg_cmd, cfg_cmd_wr, cfg_addr, cfg_addr_wr, cfg_len, cfg_len_wr,
    cfg_clkdiv, cfg_clkdiv_wr, cfg_status, cfg_status_wr, cfg_irq_en, cfg_irq_en_wr);
  modport monitor (input cfg_cmd, cfg_cmd_wr, cfg_addr, cfg_addr_wr, cfg_len, cfg_len_wr, cfg_clkdiv,
    cfg_clkdiv_wr, cfg_status, cfg_status_wr, cfg_irq_en, cfg_irq_en_wr, sts_status);
endinterface
